




import time
from character_sheets import player
from parameters import para

def stalkt1():
    print("You feel like you're being watched")
    time.sleep(para.Swait)
    print("[Sanity -10]")
    player.sanity -= 10

def stalkt2():
    print("You hear footsteps behind you")
    time.sleep(para.Swait)
    print("[Sanity -10]")
    player.sanity -= 10

def stalkt3():
    print("You spot a figure watching you from the shadows")
    time.sleep(para.Swait)
    print("[Sanity -10]")
    player.sanity -= 10

def stalkt4():
    print("The figure in the shadows seems to be getting closer and closer")
    time.sleep(para.Swait)
    print("[Sanity -10]")
    player.sanity -= 10

stalktext = [stalkt1, stalkt2, stalkt3, stalkt4]






